/** Contract-based test harness for the initialize entry point
  */
pub fn testInitializeCB() -> HarnessResult
{
  // [InvokeEntryPoint]: Invoke the entry point
  crate::lifecycle_governor_process_lifecycle_governor_initialize();

  // [RetrieveOutState]: retrieve values of the output ports via get operations and GUMBO declared local state variable
  let current_phase = get_current_phase();
  let recovery_required = get_recovery_required();
  let api_commanded_phase_report = get_commanded_phase_report();
  let api_decision_disposition = get_decision_disposition();
  let api_selected_phase = get_selected_phase();

  // [CheckPost]: invoke the oracle function
  if !GUMBOX::initialize_IEP_Post (current_phase, recovery_required, api_commanded_phase_report, api_decision_disposition, api_selected_phase) {
    return HarnessResult::FailedPostcondition(
      TestCaseError::Fail("Postcondition failed: incorrect output behavior".into())
    );
  }

  return HarnessResult::Passed
}

